import{_ as o,o as t,c as e,a5 as r}from"./chunks/framework.BEZBAInb.js";const _=JSON.parse('{"title":"Konado 腳本","description":"","frontmatter":{"title":"Konado 腳本","order":1},"headers":[],"relativePath":"tc/latest/tutorial/script/konado-script.md","filePath":"tc/latest/tutorial/script/konado-script.md","lastUpdated":1788455378000}'),i={name:"tc/latest/tutorial/script/konado-script.md"};function d(n,a,c,l,s,p){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="konadoscript" tabindex="-1">KonadoScript <a class="header-anchor" href="#konadoscript" aria-label="Permalink to &quot;KonadoScript&quot;">​</a></h1><p>KonadoScript 是一種為視覺小說量身打造的創作語言（檔案副檔名為 <code>.ks</code>）。</p><p>你可以把它想像成一種更強大、更結構化的「小說劇本」：開發者無需編寫複雜程式碼，就能控制劇情對話、角色立繪、背景切換、音樂音效，以及故事分支和選項。</p><h2 id="設計理念" tabindex="-1">設計理念 <a class="header-anchor" href="#設計理念" aria-label="Permalink to &quot;設計理念&quot;">​</a></h2><p>KonadoScript 的核心設計理念是將<strong>故事內容</strong>與<strong>程式邏輯</strong>分離：</p><ul><li>編劇專注於敘事內容，無需程式設計知識</li><li>程式設計師專注於引擎開發，無需介入故事創作</li><li>資源管理（圖片、音訊）透過識別符引用，與腳本解耦</li><li>模組化指令集，易於擴充新功能</li><li>相容版本控制系統（Git 等）</li><li>文字格式天生跨平台</li><li>資源引用與平台無關</li></ul><h2 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h2><h3 id="_1-如何處理解析錯誤" tabindex="-1">1. 如何處理解析錯誤 <a class="header-anchor" href="#_1-如何處理解析錯誤" aria-label="Permalink to &quot;1. 如何處理解析錯誤&quot;">​</a></h3><p>Godot 腳本編輯器會即時顯示 KonadoScript 的語法與語意問題。無效內容仍可儲存到 <code>.ks</code> 原始檔，但不會更新目前的執行期 <code>KonadoShot</code>；修正錯誤並再次儲存後，資源載入器會自動重新編譯，不需要手動重新匯入。</p><h3 id="_2-腳本檔案編碼問題" tabindex="-1">2. 腳本檔案編碼問題 <a class="header-anchor" href="#_2-腳本檔案編碼問題" aria-label="Permalink to &quot;2. 腳本檔案編碼問題&quot;">​</a></h3><p>請確保腳本檔案編碼為 UTF-8，否則可能出現亂碼。預設情況下建立的腳本檔案編碼為 UTF-8。</p><h3 id="_3-匯出後的劇本保護" tabindex="-1">3. 匯出後的劇本保護 <a class="header-anchor" href="#_3-匯出後的劇本保護" aria-label="Permalink to &quot;3. 匯出後的劇本保護&quot;">​</a></h3><p>匯出專案時，Konado 會讀取目前匯出預設中 <code>Konado -&gt; Script Encryption Key</code> 的值，並自動加密已編譯的 <code>.ks</code> 劇情資料。如果金鑰為空或格式錯誤，Konado 會產生一個隨機的 256 位元金鑰並用於本次建置。之後的匯出會重複使用該金鑰，除非開發者手動修改。</p><p>發佈修補程式或熱更新時，基礎套件與更新套件必須使用相同的匯出預設和金鑰。金鑰儲存在 <code>.godot/konado_export_credentials.cfg</code>，如果需要長期使用請自行備份。</p><p>本機匯出時，Godot 終端會顯示本次建置的完整金鑰，方便開發者記錄與排查問題。本功能用於避免一般工具從 PCK 直接讀取劇情明文，不能取代專用 DRM；能夠針對性分析匯出資源、客戶端程式碼或執行階段記憶體的攻擊者，仍可能還原劇情內容。</p>',15)])])}const u=o(i,[["render",d]]);export{_ as __pageData,u as default};
